services:
  donetick:
    image: donetick/donetick:v0.1.76
    restart: unless-stopped
    ports:
      - "2021:2021"
    environment:
      - DT_ENV=selfhosted
      - DT_NAME=donetick
      - DT_SERVER_PUBLIC_HOST=https://donetick-5nyvi89p.redu.cloud
      - DT_JWT_SECRET=[REDACTED:value]}
      # ANYTHING other than the exact string "postgres" silently means SQLite.
      - DT_DATABASE_TYPE=postgres
      - DT_DATABASE_HOST=${PGHOST}
      - DT_DATABASE_PORT=${PGPORT}
      - DT_DATABASE_USER=${PGUSER}
      - DT_DATABASE_PASSWORD=[REDACTED:value]}
      - DT_DATABASE_NAME=${PGDATABASE}
      # Application clock (due dates + scheduler). The DB session TZ is hardcoded upstream.
      - TZ=Europe/London

